async function evaluate(ctx: RuleContext<'P-03'>): Promise<RuleResult> {
  const participant = await ctx.db.participant.findById(ctx.input.participantId);
  if (!participant) return ctx.fail({ ruleId: 'P-03', severity: 'BLOCK',
    message: 'Participant not found', field: 'participantId' });
  if (participant.kycStatus !== 'complete') {
    return ctx.fail({ ruleId: 'P-03', severity: 'BLOCK',
      message: ctx.locale === 'pt' ? 'KYC/KYB incompleto.' : 'KYC/KYB incomplete.',
      field: 'kycStatus' });
  }
  const kycDoc = await ctx.db.document.findOne({ where: {
    participantId: participant.id, type: 'kyc_kyb_record' } });
  if (!kycDoc) {
    return ctx.fail({ ruleId: 'P-03', severity: 'BLOCK',
      message: 'kyc_kyb_record document missing', field: 'documents' });
  }
  return ctx.pass({ ruleId: 'P-03' });
}

async function evaluate(ctx: RuleContext<'P-05'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p?.exclusivityFlag) {
    return ctx.fail({ ruleId: 'P-05', severity: 'BLOCK',
      message: 'exclusivity_flag not TRUE', field: 'exclusivityFlag' });
  }
  const ack = await ctx.db.document.findOne({ where: {
    participantId: p.id, type: 'contract_exclusivity_ack' } });
  if (!ack) {
    return ctx.fail({ ruleId: 'P-05', severity: 'BLOCK',
      message: 'contract_exclusivity_ack missing', field: 'documents' });
  }
  return ctx.pass({ ruleId: 'P-05' });
}

async function evaluate(ctx: RuleContext<'P-66'>): Promise<RuleResult> {
  const massid = ctx.input.massid;
  const externalCheck = await ctx.externalRegistry.checkClaim({
    massidHash: massid.hash,
    payloadHash: massid.payloadHash,
    scopes: ['VERRA', 'PLASTICBANK', 'RECYCLASS_TRACE', 'OTHER']
  });
  if (externalCheck.flag === true) {
    await ctx.db.massid.update({ where: { id: massid.id },
      data: { externalClaimFlag: true, exceptionState: 'PENDING_REVIEW' } });
    await ctx.eventBus.emit('bad_actor_candidate', { massidId: massid.id, source: externalCheck.source });
    return ctx.fail({ ruleId: 'P-66', severity: 'BLOCK',
      message: `Conflicting claim detected at ${externalCheck.source}`, field: 'externalClaimFlag' });
  }
  return ctx.pass({ ruleId: 'P-66' });
}

async function evaluate(ctx: RuleContext<'PG-01'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  const requiredIndiv = ['kycFullName', 'kycMobile', 'kycBirthdate', 'kycEmail', 'kycResidentialAddress'];
  const missing = requiredIndiv.filter(f => !p?.[f] || String(p[f]).trim() === '');
  if (missing.length > 0) {
    return ctx.fail({ ruleId: 'PG-01', severity: 'BLOCK',
      message: `KYC fields missing: ${missing.join(', ')}`, field: missing[0] });
  }
  if (p.participantType === 'business' || p.participantType === 'INT') {
    const reqBiz = ['companyLegalName', 'companyRegistration', 'companyAddress'];
    const missingBiz = reqBiz.filter(f => !p?.[f]);
    if (missingBiz.length > 0) {
      return ctx.fail({ ruleId: 'PG-01', severity: 'BLOCK',
        message: `Business KYB fields missing: ${missingBiz.join(', ')}`, field: missingBiz[0] });
    }
  }
  return ctx.pass({ ruleId: 'PG-01' });
}

async function evaluate(ctx: RuleContext<'PG-02'>): Promise<RuleResult> {
  const chain = await ctx.db.getChainParticipants(ctx.input.massidId);
  const issues = [];
  for (const p of chain) {
    if (p.tcAcceptanceFlag !== true) issues.push({ pid: p.id, field: 'tcAcceptanceFlag' });
    if (p.dataRightsAckFlag !== true) issues.push({ pid: p.id, field: 'dataRightsAckFlag' });
  }
  if (issues.length > 0) {
    return ctx.fail({ ruleId: 'PG-02', severity: 'BLOCK',
      message: `T&C or data-rights missing for ${issues.length} participants`,
      field: 'chain.participants' });
  }
  return ctx.pass({ ruleId: 'PG-02' });
}

async function evaluate(ctx: RuleContext<'PG-03'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  const strictJurisdictions = ctx.config.get('jurisdiction_aml_strict'); // ['EU', 'BR', 'US', 'UK']
  const isStrict = strictJurisdictions.includes(p.countryCode);
  if (p.amlCftAckFlag !== true) {
    const sev = isStrict ? 'BLOCK' : 'FLAG';
    return ctx.fail({ ruleId: 'PG-03', severity: sev,
      message: 'AML/CFT acknowledgement missing', field: 'amlCftAckFlag' });
  }
  return ctx.pass({ ruleId: 'PG-03' });
}

async function evaluate(ctx: RuleContext<'PG-04'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p.walletAddress || p.walletAddress.trim() === '') {
    return ctx.fail({ ruleId: 'PG-04', severity: 'BLOCK',
      message: 'Wallet address missing', field: 'walletAddress' });
  }
  if (!ctx.crypto.isValidEvmAddress(p.walletAddress)) {
    return ctx.fail({ ruleId: 'PG-04', severity: 'BLOCK',
      message: 'Wallet address invalid format', field: 'walletAddress' });
  }
  const banned = ctx.config.get('jurisdiction_crypto_banned');
  if (banned.includes(p.countryCode)) {
    return ctx.fail({ ruleId: 'PG-04', severity: 'BLOCK',
      message: 'Crypto rewards not allowed in jurisdiction', field: 'countryCode' });
  }
  if (p.digitalAssetLawAckFlag !== true) {
    return ctx.fail({ ruleId: 'PG-04', severity: 'FLAG',
      message: 'Digital asset law acknowledgement pending', field: 'digitalAssetLawAckFlag' });
  }
  return ctx.pass({ ruleId: 'PG-04' });
}

async function evaluate(ctx: RuleContext<'PG-15'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (p.laborComplianceAckFlag !== true) {
    return ctx.fail({ ruleId: 'PG-15', severity: 'FLAG',
      message: 'ILO labor compliance acknowledgement missing', field: 'laborComplianceAckFlag' });
  }
  if (['R', 'P'].includes(p.participantType) && !p.laborComplianceDocRef) {
    return ctx.fail({ ruleId: 'PG-15', severity: 'BLOCK',
      message: 'Labor compliance documentation missing for Recycler/Processor',
      field: 'laborComplianceDocRef' });
  }
  return ctx.pass({ ruleId: 'PG-15' });
}

async function evaluate(ctx: RuleContext<'PG-16'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (p.dataPrivacyAckFlag !== true) {
    return ctx.fail({ ruleId: 'PG-16', severity: 'FLAG',
      message: 'Data privacy acknowledgement missing', field: 'dataPrivacyAckFlag' });
  }
  if (p.participantType === 'INT' && !p.dpaRef) {
    return ctx.fail({ ruleId: 'PG-16', severity: 'BLOCK',
      message: 'DPA (Data Processing Agreement) missing for INT', field: 'dpaRef' });
  }
  return ctx.pass({ ruleId: 'PG-16' });
}
